SELECT  FROM alert_records

    AND server_id = #{serverId}
    AND status = #{status}

ORDER BY triggered_at DESC, id DESC LIMIT #{offset}, #{pageSize}

SELECT COUNT(id) FROM alert_records

    AND server_id = #{serverId}
    AND status = #{status}
